"use client";
import { usePlanCheckout, errorMessage, periodLabel } from '@paykit/react';
import { installmentSplit, formatUsdt, type CheckoutInput, type PlanOption } from '@paykit/js';
import './paykit-ui.css';

export function CustomInstallmentPlan({ input, total, option, className = '' }: { input: CheckoutInput; total: string; option: PlanOption; className?: string }) {
  const plan = usePlanCheckout();
  const amounts = installmentSplit(BigInt(total), option.count, option.downPaymentPercent ?? 0);
  return <section className={`pkc-card ${className}`} aria-label="Installment plan">
    <div className="pkc-row"><h3 className="pkc-title">Pay over time</h3><span className="pkc-tag">{option.count} payments</span></div>
    <p className="pkc-amount">{formatUsdt(amounts.installmentAmount)} <span>USDT per payment</span></p>
    <p className="pkc-muted">{option.count} payments, every {periodLabel(option.periodSeconds)}. Total {formatUsdt(total)} USDT.</p>
    {amounts.downPayment > 0n && <p className="pkc-muted">{formatUsdt(amounts.downPayment)} USDT down payment</p>}
    <p className="pkc-muted">You sign consent and a bounded token allowance. No customer gas is required.</p>
    <button className="pkc-button" disabled={plan.busy || plan.phase === 'done'} onClick={() => { void plan.start(input, option, total).catch(() => {}); }}>{plan.busy ? 'Setting up plan…' : plan.phase === 'done' ? 'Plan created' : 'Set up plan'}</button>
    {plan.error != null && <p className="pkc-error" role="alert">{errorMessage(plan.error)}</p>}
    {plan.plan && <p className="pkc-muted" role="status">Plan {plan.plan.status}. You can cancel future payments from your account.</p>}
  </section>;
}

/* Own this stylesheet. Money and signing logic stays in @paykit/react hooks. */
.pkc-card {
  display: grid; gap: 16px; width: 100%; padding: 24px;
  border: 1px solid var(--pk-line, #dce2de); border-radius: var(--pk-radius-lg, 14px);
  background: var(--pk-surface, #fff); color: var(--pk-ink, #28323a); font: inherit;
}
.pkc-card *, .pkc-wallet * { box-sizing: border-box; }
.pkc-card p, .pkc-card h3 { margin: 0; }
.pkc-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.pkc-title { font-size: 1.1rem; font-weight: 650; line-height: 1.3; }
.pkc-muted { color: var(--pk-muted, #5f6b72); font-size: .875rem; line-height: 1.6; }
.pkc-button {
  padding: 12px 18px; border: 1px solid transparent; border-radius: var(--pk-radius, 10px);
  background: var(--pk-accent, #0f4c45); color: var(--pk-accent-ink, #fff);
  font: inherit; font-weight: 600; cursor: pointer; min-height: 44px;
}
.pkc-button:hover:not(:disabled) { filter: brightness(1.12); }
.pkc-button:disabled { opacity: .6; cursor: default; }
.pkc-button:focus-visible, .pkc-link:focus-visible { outline: 3px solid var(--pk-focus, #1a7f72); outline-offset: 3px; }
.pkc-button--quiet { background: transparent; color: var(--pk-ink, #28323a); border-color: var(--pk-line, #dce2de); }
.pkc-error { color: var(--pk-bad, #b42318); font-size: .875rem; }
.pkc-tag { padding: 4px 9px; border-radius: 6px; background: var(--pk-accent-soft, #e3efec); color: var(--pk-ink, #28323a); font-size: .8rem; }
.pkc-link { color: var(--pk-accent, #0f4c45); text-underline-offset: 3px; }
.pkc-wallet { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.pkc-steps { list-style: none; display: flex; padding: 0; margin: 0; gap: 6px; }
.pkc-steps li { flex: 1; border-top: 4px solid var(--pk-line, #dce2de); padding-top: 9px; font-size: .75rem; color: var(--pk-muted, #5f6b72); }
.pkc-steps li[data-complete="true"] { border-color: var(--pk-accent, #0f4c45); color: var(--pk-ink, #28323a); }
.pkc-details { margin: 0; display: grid; gap: 12px; }
.pkc-details div { display: flex; justify-content: space-between; gap: 12px; }
.pkc-details dt { color: var(--pk-muted, #5f6b72); }
.pkc-details dd { margin: 0; text-align: right; overflow-wrap: anywhere; }
.pkc-amount { font-size: 2rem; font-variant-numeric: tabular-nums; font-weight: 650; }
.pkc-amount span { font-size: .875rem; font-weight: 400; color: var(--pk-muted, #5f6b72); }
.pkc-product-image { width: 100%; max-height: 220px; object-fit: cover; border-radius: 8px; }
